<?php require_once 'config.php'; if(logged()) redirect(is_admin()?'admin/index.php':'index.php'); $pageTitle='Entrar';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$email=trim(strtolower($_POST['email']??''));$senha=$_POST['senha']??'';if($email===''||$senha==='')$error='Preencha e-mail e senha.';else{$s=db()->prepare('SELECT id,nome,email,senha,tipo,criado_em FROM usuarios WHERE email=?');$s->execute([$email]);$u=$s->fetch();if($u&&password_verify($senha,$u['senha'])){session_regenerate_id(true);unset($u['senha']);$_SESSION['user']=$u;redirect($u['tipo']==='administrador'?'admin/index.php':'index.php');}else $error='E-mail ou senha inválidos.';}} require 'includes/header.php'; ?>
